import { useMemo } from "react";
import dayjs from "dayjs";
export const zoned = (date, timezone) => timezone === "UTC" ? dayjs.utc(date) : dayjs.tz(date, timezone);
const useSafeTimezone = (timezone) => {
    const safeTimezone = useMemo(() => {
        if (!timezone) {
            return {
                formattedTimezone: "UTC+00:00",
                ianaTimezone: "UTC",
            };
        }
        try {
            const offset = dayjs().tz(timezone).format("Z");
            return {
                formattedTimezone: `UTC${offset}`,
                ianaTimezone: timezone,
            };
        }
        catch (error) {
            return {
                formattedTimezone: "UTC+00:00",
                ianaTimezone: "UTC",
            };
        }
    }, [timezone]);
    return safeTimezone;
};
export default useSafeTimezone;
